parameters.jsCode:
// Parse GPT response and merge with original articles
const batchItems = $input.first();
const gptResponse = batchItems.json.message.content;

let analyses = [];
try {
  // Clean response (remove markdown if present)
  const cleaned = gptResponse.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  analyses = JSON.parse(cleaned);
  if (!Array.isArray(analyses)) analyses = [analyses];
} catch(e) {
  console.error('Failed to parse GPT response:', e.message);
  return [];
}

// Map source URL to source name
function getSourceName(url) {
  if (!url) return 'Unknown';
  if (url.includes('economictimes')) return 'Economic Times';
  if (url.includes('vccircle')) return 'VCCircle';
  if (url.includes('inc42')) return 'Inc42';
  if (url.includes('e27')) return 'e27';
  if (url.includes('techinasia')) return 'Tech In Asia';
  if (url.includes('linkedin')) return 'LinkedIn';
  return url.split('/')[2] || 'Unknown';
}

return analyses
  .filter(a => a && a.title && a.relevance_score >= 40)
  .map(a => ({
    json: {
      title: a.title || '',
      summary: a.summary || '',
      ai_summary: a.ai_summary || a.summary || '',
      company: a.company || null,
      type: a.type || 'general',
      implication: a.implication || '',
      modules: a.modules || ['briefing'],
      tags: a.tags || [],
      relevance_score: a.relevance_score || 50,
      source: a.source || 'RSS',
      source_url: a.source_url || null,
      published_at: new Date().toISOString()
    }
  }));
